package local.pocketchat;

import java.io.*;
import java.nio.file.*;
import java.util.UUID;
import org.json.*;

/** Production journal/model and actual host filesystem boundaries only. No
 * Android process, SQLite, Keystore or browser-cookie acceptance is claimed. */
public final class EnvironmentLifecyclePolicyTest {
  static JSONArray checks=new JSONArray();
  interface Work{void run()throws Exception;}
  static void check(String name,boolean value){checks.put(J.obj("name",name,"pass",value));if(!value)throw new AssertionError(name);}
  static void rejects(String name,Work work)throws Exception{boolean rejected=false;try{work.run();}catch(IOException|IllegalArgumentException|JSONException expected){rejected=true;}check(name,rejected);}
  public static void main(String[] args)throws Exception{
    check("Default browser process owns slot zero",EnvironmentProcessPolicy.owns("example.app","example.app",0));check("Profile process owns only its slot",EnvironmentProcessPolicy.owns("example.app","example.app:profile3",3)&&!EnvironmentProcessPolicy.owns("example.app","example.app:profile3",0));check("Maintenance process must refresh slot zero preferences",!EnvironmentProcessPolicy.owns("example.app","example.app:engine_restart",0));check("Management fixture also reads slot zero cross-process",!EnvironmentProcessPolicy.owns("example.app","example.app:management_test",0));check("Gecko child is not the preference owner",!EnvironmentProcessPolicy.owns("example.app","example.app:gecko_env0_tab",0));check("Unknown process never assumes local preference ownership",!EnvironmentProcessPolicy.owns("example.app",null,0));
    EnvironmentSpec.Identity old=new EnvironmentSpec.Identity(1,3,UUID.randomUUID().toString());EnvironmentSpec original=EnvironmentSpecMigration.fromLegacy(old,true,1,"external",new JSONObject(),"socks://example.test:1080").withApplied(1,"Gecko fixture",1).withObservation(1,J.obj("actual","previous"),2);
    EnvironmentResetPlan staged=EnvironmentResetPlan.start(original);check("Reset keeps logical UUID and advances generation",staged.next.environmentId.equals(old.environmentId)&&staged.next.generation==4&&staged.next.slot==1);check("Staged reset does not invent cleaned/applied data",!staged.frozen()&&staged.after==null);check("Staged journal roundtrip retains old configuration",EnvironmentResetPlan.read(staged.bytes()).before.desired().equals(original.desired()));
    EnvironmentResetPlan frozen=staged.freeze(original.desired().network,new JSONObject());check("Reset keeps desired configuration",frozen.after.desired().equals(original.desired()));check("Reset retires runtime and website acknowledgements",frozen.after.appliedRevision==0&&frozen.after.observedRevision==0&&frozen.after.engineVersion.isEmpty()&&frozen.after.observations().length()==0);check("Desired revision does not change for unchanged config",frozen.after.desiredRevision==original.desiredRevision);check("Frozen journal roundtrip retains new identity",EnvironmentResetPlan.read(frozen.bytes()).after.identity.equals(frozen.next));
    JSONObject queued=J.obj("action","external","config",J.obj("proxy","socks://next.example:1080"),"baseline","stable-hash","environmentIntent",J.obj("schema",1,"id",UUID.randomUUID().toString().replace("-",""),"state","ready","identity",old.json()),"baselineLineage",J.obj("generation",old.generation));
    EnvironmentSpec.NetworkBinding candidate=EnvironmentSpecMigration.fromLegacy(old,true,1,"external",new JSONObject(),"socks://next.example:1080").desired().network;
    EnvironmentResetPlan pending=staged.freeze(candidate,queued);check("Pending desired route takes priority over active route",pending.after.desired().network.credentialRevision.equals(candidate.credentialRevision)&&!pending.after.desired().network.credentialRevision.equals(original.desired().network.credentialRevision));check("Pending browser configuration remains unchanged",new EnvironmentSpec.Configuration(pending.after.desired().browser(),original.desired().network).equals(original.desired()));check("Pending receipt is rebound to new generation",pending.pending().getJSONObject("environmentIntent").getJSONObject("identity").optInt("generation")==4);check("Pending candidate and baseline remain intact",pending.pending().getJSONObject("config").optString("proxy").equals("socks://next.example:1080")&&pending.pending().optString("baseline").equals("stable-hash"));check("Old generation lineage is not carried into reset",!pending.pending().has("baselineLineage"));check("Rebinding cannot mutate original queued intent",queued.getJSONObject("environmentIntent").getJSONObject("identity").optInt("generation")==3);
    JSONObject unfinished=new JSONObject(queued.toString());unfinished.getJSONObject("environmentIntent").put("state","staged");rejects("Interrupted network stage must recover before reset freezes",()->staged.freeze(candidate,unfinished));JSONObject foreign=new JSONObject(queued.toString());foreign.getJSONObject("environmentIntent").getJSONObject("identity").put("environmentId",UUID.randomUUID().toString());rejects("Foreign pending identity is rejected",()->staged.freeze(candidate,foreign));
    rejects("Reset cannot replace logical UUID",()->original.afterLoginReset(new EnvironmentSpec.Identity(1,4,UUID.randomUUID().toString())));rejects("Reset cannot move storage slot",()->original.afterLoginReset(new EnvironmentSpec.Identity(2,4,old.environmentId)));rejects("Reset cannot skip generation",()->original.afterLoginReset(new EnvironmentSpec.Identity(1,5,old.environmentId)));rejects("Reset generation overflow is rejected",()->EnvironmentResetPlan.start(EnvironmentSpec.initial(new EnvironmentSpec.Identity(1,Integer.MAX_VALUE,old.environmentId),original.desired())));
    JSONObject bad=new JSONObject(new String(frozen.bytes(),java.nio.charset.StandardCharsets.UTF_8));bad.put("schema",2);rejects("Unknown journal schema never becomes a default",()->EnvironmentResetPlan.read(bad.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));rejects("Journal trailing data is rejected",()->EnvironmentResetPlan.read((new String(frozen.bytes(),java.nio.charset.StandardCharsets.UTF_8)+"junk").getBytes(java.nio.charset.StandardCharsets.UTF_8)));
    Path base=Files.createTempDirectory("environment-cleanup-");try{
      File noBackup=new File(base.toFile(),"no_backup"),cache=new File(base.toFile(),"cache");noBackup.mkdir();cache.mkdir();File root=EnvironmentBrowserData.root(noBackup,0);File other=EnvironmentBrowserData.root(noBackup,1);Files.write(new File(root,"network.sealed").toPath(),new byte[]{1});Files.write(new File(root,"shared-library").toPath(),new byte[]{2});Files.write(new File(other,"other-site").toPath(),new byte[]{3});File browser=new File(root,"gecko-browser");browser.mkdir();Files.write(new File(browser,"cookies.sqlite").toPath(),new byte[]{4});Files.createSymbolicLink(new File(browser,"outside").toPath(),new File(other,"other-site").toPath());Files.createSymbolicLink(new File(browser,"dangling").toPath(),base.resolve("absent"));for(String name:new String[]{"gecko-session.json","gecko-session.json.bak","gecko-session.json.new"})Files.write(new File(root,name).toPath(),new byte[]{5});File uploads=new File(cache,"gecko-uploads");uploads.mkdir();Files.write(new File(uploads,"photo.png").toPath(),new byte[]{6});File saved=new File(cache,"saved-file");Files.write(saved.toPath(),new byte[]{7});
      EnvironmentBrowserData.clear(root,cache);check("Target site directory and checkpoints are removed",!browser.exists()&&!new File(root,"gecko-session.json").exists()&&!new File(root,"gecko-session.json.bak").exists()&&!new File(root,"gecko-session.json.new").exists());check("Slot zero root and network secret survive",root.isDirectory()&&new File(root,"network.sealed").isFile());check("Shared library survives",new File(root,"shared-library").isFile());check("Another environment survives including linked target",new File(other,"other-site").isFile());check("Only upload staging is removed from cache",!uploads.exists()&&saved.isFile());EnvironmentBrowserData.clear(root,cache);check("Partial cleanup retries are idempotent",root.isDirectory()&&saved.isFile());
      File linked=new File(noBackup,"profiles/env2");Files.createSymbolicLink(linked.toPath(),other.toPath());rejects("Linked environment ancestor refuses cleanup admission",()->EnvironmentBrowserData.root(noBackup,2));check("Refusing ancestor preserves other environment",new File(other,"other-site").isFile());File invalid=new File(base.toFile(),"linked-base");invalid.mkdir();Files.createSymbolicLink(new File(invalid,"profiles").toPath(),new File(noBackup,"profiles").toPath());rejects("Linked profiles ancestor is rejected",()->EnvironmentBrowserData.root(invalid,3));rejects("Invalid slot cannot resolve a cleanup root",()->EnvironmentBrowserData.root(noBackup,8));File linkedRoot=new File(base.toFile(),"linked-root");Files.createSymbolicLink(linkedRoot.toPath(),other.toPath());rejects("Linked trusted root cannot redirect slot zero cleanup",()->EnvironmentBrowserData.root(linkedRoot,0));rejects("Missing trusted root cannot become a cleanup scope",()->EnvironmentBrowserData.root(new File(base.toFile(),"missing-root"),0));
    }finally{EnvironmentBrowserData.erase(base.toFile());}
    System.out.println(J.obj("status","passed","actualAndroidExecution",false,"scope","Production reset model/journal plus actual JVM temporary-file cleanup; no Android SQLite/process/Keystore/Gecko claim","passed",checks.length(),"total",checks.length(),"checks",checks));
  }
}
